class NumberConverter:

    @staticmethod
    def decimal_to_binary(decimal_num):
        if not isinstance(decimal_num, int):
            raise ValueError('Input must be a valid integer.')
        if decimal_num < 0:
            raise ValueError('Input must be a non-negative integer.')
        if decimal_num == 0:
            return '0'
        binary_num = ''
        while decimal_num > 0:
            binary_num = str(decimal_num % 2) + binary_num
            decimal_num //= 2
        return binary_num

    @staticmethod
    def binary_to_decimal(binary_num):
        if not all((char in '01' for char in binary_num)):
            raise ValueError('Input contains non-binary characters')
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise TypeError('Input must be an integer.')
        if decimal_num < 0:
            raise ValueError('Input must be a non-negative integer.')
        if decimal_num == 0:
            return '0'
        octal_num = ''
        while decimal_num > 0:
            octal_num = str(decimal_num % 8) + octal_num
            decimal_num //= 8
        return octal_num

    @staticmethod
    def octal_to_decimal(octal_num):
        """Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        """
        if not all((char in '01234567' for char in octal_num)):
            raise ValueError('Invalid octal number')
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise TypeError('Input must be an integer')
        if decimal_num < 0:
            raise ValueError('Input must be a non-negative integer')
        if decimal_num == 0:
            return '0'
        hex_chars = '0123456789abcdef'
        hex_num = ''
        while decimal_num > 0:
            remainder = decimal_num % 16
            hex_num = hex_chars[remainder] + hex_num
            decimal_num //= 16
        return hex_num

    @staticmethod
    def hex_to_decimal(hex_num):
        """Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        """
        if not isinstance(hex_num, str) or not hex_num:
            raise ValueError('Input must be a non-empty string.')
        if not all((char in '0123456789abcdefABCDEF' for char in hex_num)):
            raise ValueError('Input must be a valid hexadecimal string.')
        return int(hex_num, 16)

